const t=(key)=>DICT[state.lang]?.[key]||DICT.en[key]||key;
const CATEGORY_LABEL_KEYS=Object.freeze({ 'Build & Buy':'buildbuy','Gameplay Mod':'mods',Hair:'hair',Clothing:'clothing',Makeup:'makeup',Accessories:'accessories',Furniture:'furniture',Lashes:'lashes',Eyebrows:'eyebrows' });
const categoryLabel=(v)=>CATEGORY_LABEL_KEYS[v]?t(CATEGORY_LABEL_KEYS[v]):v;
const safeRead=(key,fallback)=>{try{const v=JSON.parse(localStorage.getItem('simmerspace-'+key));return v??fallback}catch{return fallback}};
const safeWrite=(key,value)=>{try{localStorage.setItem('simmerspace-'+key,JSON.stringify(value));return true}catch{return false}};
const safeGet=(key)=>{try{return localStorage.getItem(key)}catch{return null}};
const safeSet=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
function normalizePatreonProfile(raw){try{const url=new URL(String(raw).trim());if(url.protocol!=='https:'||!['patreon.com','www.patreon.com'].includes(url.hostname.toLowerCase())||url.username||url.password||(url.port&&url.port!=='443'))return null;const profilePath=url.pathname.replace(/\/+$/,'');const firstSegment=profilePath.split('/').filter(Boolean)[0]?.toLowerCase();if(!firstSegment||['login','oauth2','api','about','home','settings'].includes(firstSegment))return null;url.hostname='www.patreon.com';url.pathname=profilePath;url.search='';url.hash='';return url.href.replace(/\/$/,'')}catch{return null}}
function localPatreonCreators(){const saved=safeRead('patreon-creators',[]);if(!Array.isArray(saved))return[];return saved.flatMap(c=>{if(!c||typeof c.name!=='string'||typeof c.id!=='string')return[];const profileUrl=normalizePatreonProfile(c.profileUrl);return profileUrl?[{...c,profileUrl,icon:'P',platforms:[['Patreon',profileUrl]],tags:[],type:'Unknown',style:'Patreon profile',esStyle:'Perfil de Patreon',manualPatreon:true}]:[]})}
function creatorCatalog(){return [...CREATORS,...localPatreonCreators()]}
function savedTheme(){const value=safeGet('simmerspace-theme');if(value==='dark')return'dark-lavender';if(value==='light'||!value)return'soft-lavender';return /^(soft|dark)-(rose|lavender|sage)$/.test(value)?value:'soft-lavender'}
const state={page:'discover',parent:'all',sub:'All',gender:'All',age:'All ages',style:'All',source:'All',sort:'curated',query:'',libraryQuery:'',libraryState:'All',creatorPlatform:'All',creatorFollowingOnly:false,followingCreators:safeRead('following-creators',[]),groupMode:safeGet('simmerspace-group-mode')||'category',filtersOpen:false,favorites:safeRead('favorites',[]),collections:safeRead('collections',SEED_COLLECTIONS),statuses:safeRead('statuses',{}),theme:savedTheme(),lang:safeGet('simmerspace-language')||(navigator.language?.toLowerCase().startsWith('es')?'es':'en'),activeCollection:null,activeBoard:null};
const content=document.getElementById('page-content'),search=document.getElementById('search-input'),overlay=document.getElementById('overlay'),dialog=document.getElementById('dialog');
let modsScanResult=null,modsScanProgress=null,modsScanBusy=false,modsScanError='',modsScanQuery='',modsScanPage=0;
const MODS_SCAN_PAGE_SIZE=100;
function persist(){safeWrite('favorites',state.favorites);safeWrite('collections',state.collections);safeWrite('statuses',state.statuses)}
function getBoards(){const saved=safeRead('boards',SEED_BOARDS);if(!Array.isArray(saved))return structuredClone(SEED_BOARDS);return saved.map((b,i)=>({...b,refs:Array.isArray(b.refs)?b.refs:[],note:b.note||'',used:b.used||saved.length-i}))}
function boardLabel(b){if(state.lang!=='es')return b.name;return({rooms:'Rincones donde viviría',sims:'Sims con una historia',wardrobe:'Ideas para el clóset',beauty:'Pequeños detalles de belleza',builds:'Construcciones y rincones',colors:'Colores favoritos'})[b.id]||b.name}
function boardDescription(b){if(state.lang!=='es')return b.note||'';return({rooms:'Madera cálida, plantas y un rincón soleado para leer.',sims:'Pequeños detalles que hacen que cada Sim tenga su propia historia.',wardrobe:'',beauty:'',builds:'',colors:''})[b.id]??(b.note||'')}
function collectionLabel(c){if(state.lang!=='es')return c.name;return({'soft-life':'Vida tranquila','build-inspo':'Hallazgos de Construir y comprar','dream-sims':'Sims soñados'})[c.id]||c.name}
function audienceLabel(value){if(state.lang!=='es')return value;return({Female:'Femenino',Male:'Masculino',Unisex:'Unisex','All ages':'Todas las edades',Teen:'Adolescente','Young Adult':'Joven adulto',Kids:'Niños',Toddlers:'Niños pequeños'})[value]||value}
function styleLabel(value){if(value==='Both')return t('both');return value}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const NOTE_ES={'soft-cloud-bob':'Un corte bob ligero con flequillo suave para el día a día.','slow-morning-set':'Un conjunto cálido de punto para mañanas tranquilas.','peachy-glow':'Un rubor durazno sutil para un acabado fresco y soleado.','little-lanterns':'Farolitos de papel para dar luz cálida a tus construcciones.','garden-party-dress':'Un vestido floral ligero para días soleados.','tiny-treasures':'Accesorios delicados con una paleta pastel.','willow-creek-kitchen':'Madera cálida y detalles verdes para una cocina acogedora.','starlight-eyes':'Ojos luminosos y suaves en tonos delicados.','mini-meadow-overalls':'Overoles juguetones con detalles de pradera.','gentle-days-mod':'Pequeños ajustes para una experiencia de juego más relajada.','lash-lines':'Pestañas sutiles para looks cotidianos.','arched-brows':'Cejas naturales y suaves en varios tonos.','toddler-cloud-onesie':'Un pijama acogedor para Sims pequeñitos.','soft-undercut':'Un peinado limpio y suave para looks cotidianos.','daisy-skater-tee':'Una playera alegre para la escuela y el parque.'};
function labelItem(item,field='name'){if(state.lang==='es'){if(field==='note')return NOTE_ES[item.id]||item.note;if(field==='name'&&item.es)return item.es}return item[field]}
function tagLabel(tag){if(state.lang!=='es')return tag;return ({Hair:'Cabello',Clothing:'Ropa',Makeup:'Maquillaje',Lashes:'Pestañas',Eyebrows:'Cejas',Furniture:'Muebles','Build & Buy':'Construir y comprar','Maxis Match':'Maxis Match',Gameplay:'Juego',Utility:'Utilidades',Lookbooks:'Lookbooks'})[tag]||tag}
function art(item,extra=''){return `<div class="art ${extra}" style="--art-height:${item.height||208}px;--art-bg:${item.bg};--shape-a:${item.a};--shape-b:${item.b};--hair:${item.hair||'#594743'};--skin:${item.skin||'#dfb9a2'};--figure:${item.figure||'#c49bab'};--figure-light:${item.light||'#e4ccd7'};--figure-dark:${item.dark||'#977785'}"><span class="art-label">SIMMERSPACE · ${t('demo')}</span><span class="art-deco"></span><span class="art-rug"></span><span class="art-figure"></span><span class="art-object">${item.emoji}</span><span class="art-sparkle">✧</span>${state.page==='mycc'?'' : `<span class="art-sticker">${esc(categoryLabel(item.category||'Pinterest'))}</span>`}</div>`}
function nav(){const pages=[['discover','✳'],['mycc','▦'],['inspiration','♡'],['creators','✧']];document.getElementById('sidebar').innerHTML=`<a class="brand" href="#discover"><span class="brand-mark"><span></span><span></span><span></span><span></span></span><span class="brand-name"><span class="brand-simmer">simmer</span><span class="brand-space">space</span></span></a><div class="side-label">${t('space')}</div><nav class="main-nav">${pages.map(([id,icon])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span>${t(id)}</span>${id==='mycc'?`<span class="nav-count">${ITEMS.length}</span>`:''}</button>`).join('')}</nav><div class="side-label side-label-spaced">${t('collections')}<button class="tiny-add" id="new-collection" aria-label="${t('newCollection')}">+</button></div><button class="collection-all" id="show-all-collections">${state.lang==='es'?'Ver todas las colecciones':'View all collections'} →</button><div class="collection-nav">${state.collections.map(c=>`<button class="nav-item ${state.page==='collection'&&state.activeCollection===c.id?'active':''}" data-collection="${esc(c.id)}"><span class="collection-dot"></span><span>${esc(collectionLabel(c))}</span></button>`).join('')}</div><div class="sidebar-bottom"><button class="nav-item ${state.page==='settings'?'active':''}" data-page="settings"><span class="nav-icon">⚙</span><span>${t('settings')}</span></button><div class="profile-card"><div class="avatar">S</div><div><strong>${t('profile')}</strong><small>${t('local')}</small></div><span class="profile-dots">···</span></div></div>`}
function setShell(){document.body.className=`theme-${state.theme}`;document.documentElement.lang=state.lang;nav();const names={discover:t('discover'),mycc:t('mycc'),inspiration:t('inspiration'),creators:t('creators'),settings:t('settings'),collection:state.collections.find(c=>c.id===state.activeCollection)?.name||t('collections')};document.getElementById('crumb-kicker').textContent=t('kicker');document.getElementById('crumb-title').textContent=names[state.page]||t('discover');document.getElementById('footer-copy').textContent=t('footer');document.getElementById('footer-version').textContent=`SimmerSpace v${APP_VERSION} demo`;search.placeholder=t('search');document.getElementById('theme-toggle').innerHTML=`<span class="theme-icon">${state.theme.startsWith('dark')?'☀':'☾'}</span>`;document.getElementById('profile-button').title=t('signIn')}
function heading(eyebrow,title,subtitle){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>`}
function empty(title=t('empty'),text=t('emptyText')){return `<div class="empty-state"><span>☁</span><b>${title}</b><div>${text}</div></div>`}
function isInCollection(item){return state.collections.some(c=>c.items.includes(item.id))}
function installState(item){const stored=state.statuses[item.id];if(stored&&typeof stored==='object')return{installed:!!stored.installed,needsUpdate:!!stored.needsUpdate};const value=typeof stored==='string'?stored:item.status;return{installed:value==='installed'||value==='update',needsUpdate:value==='update'}}
function itemStatus(item){const s=installState(item);return s.needsUpdate?'update':s.installed?'installed':isInCollection(item)?'saved':'pending'}
function itemCard(item){const liked=state.favorites.includes(item.id),saved=isInCollection(item),status=itemStatus(item),statusText={installed:t('installed'),saved:t('saved'),update:t('needsUpdate'),pending:t('pending')}[status];return `<article class="cc-card" data-detail="${item.id}">${art(item)}<div class="card-info"><div class="card-title-row"><div><h3>${esc(labelItem(item))}</h3><div class="card-creator">${esc(item.creator)}</div></div><div class="card-actions"><button class="icon-btn ${liked?'liked':''}" data-favorite="${item.id}" title="${t('favorite')}" aria-label="${t('favorite')}">${liked?'♥':'♡'}</button><button class="icon-btn ${saved?'saved':''}" data-save="${item.id}" title="${t('save')}" aria-label="${t('save')}">▤</button></div></div><div class="card-meta">${state.page==='mycc'?status==='pending'?'':`<span class="status-pill status-${status}">${esc(statusText)}</span>`:`<span class="meta-pill">${esc(item.type)}</span>`}<span class="meta-source">${esc(item.source)}</span></div></div></article>`}
function refCard(ref){return `<article class="cc-card reference-card">${art(ref)}<div class="card-info"><div class="card-title-row"><div><h3>${esc(labelItem(ref))}</h3><div class="card-creator">${t('pinterest')} · ${ref.creator}</div></div><button class="icon-btn saved" data-pin-ref="${ref.id}" title="${t('addReference')}" aria-label="${t('addReference')}">▤</button></div><div class="card-meta"><span class="meta-pill">Pinterest</span><span class="meta-source">${t('demo')}</span></div></div></article>`}
function filteredItems(){const query=state.query.toLowerCase();let items=ITEMS.filter(i=>{if(query&&!`${i.name} ${i.es} ${i.creator} ${i.category} ${i.sub} ${i.source} ${i.tag} ${i.type}`.toLowerCase().includes(query))return false;if(state.parent==='mods'&&i.department!=='mods')return false;if(state.parent==='cas'&&i.department!=='cas')return false;if(state.parent==='buildbuy'&&i.department!=='buildbuy')return false;if(state.sub==='Body'&&state.parent==='cas'&&!['Hair','Makeup','Lashes','Eyebrows','Eyes'].includes(i.sub))return false;else if(state.sub!=='All'&&state.sub!=='Body'&&i.sub!==state.sub&&i.category!==state.sub)return false;if(state.gender!=='All'&&i.gender!=='All'&&i.gender!==state.gender&&i.gender!=='Unisex')return false;if(state.age!=='All ages'&&i.age!=='All ages'&&i.age!==state.age)return false;if(state.style!=='All'&&i.type!==state.style&&i.type!=='Both')return false;if(state.source!=='All'&&i.source!==state.source)return false;return true});if(state.sort==='az')items.sort((a,b)=>labelItem(a).localeCompare(labelItem(b)));if(state.sort==='updated')items.sort((a,b)=>b.updated-a.updated);if(state.sort==='popular')items.sort((a,b)=>b.popularity-a.popularity);return items}
function renderDiscover(){state.filtersOpen=document.querySelector('.filter-disclosure')?.open??state.filtersOpen;const items=filteredItems(),parents=[['all',t('all')],['mods',t('mods')],['cas',t('cas')],['buildbuy',t('buildbuy')]],subs=SUBS[state.parent];content.innerHTML=`<section class="hero"><div><div class="eyebrow">${t('heroEyebrow')}</div><h1>${t('heroTitle').replace('\n','<br>')}</h1><p>${t('heroText')}</p></div><div class="hero-note"><i>✳</i><span><b>${t('mycc')}</b> ${state.lang==="es"?"es el corazón del gestor de mods. Descubre te ayuda a encontrar tu próximo contenido.":"is the heart of this mod manager. Discover helps you find the next great addition."} <small>${t('demo')} · ${items.length} ${t('finds')}</small></span></div></section><div class="section-toolbar"><h2>${t('filterBy')}</h2></div><div class="category-row parent-filters">${parents.map(([id,name])=>`<button class="chip ${state.parent===id?'selected':''}" data-parent="${id}">${id==='all'?'✦ ':''}${name}</button>`).join('')}</div><div class="filter-actions-row"><details class="filter-panel filter-disclosure" ${state.filtersOpen?'open':''}><summary class="filter-title">${state.parent==='cas'?`${t('cas')} › ${state.sub==='All'?t('body'):t(state.sub.toLowerCase())} › ${state.gender==='All'?t('female'):t(state.gender.toLowerCase())}`:state.parent==='buildbuy'?`${t('buildbuy')} › ${state.sub==='All'?t('furniture'):t(state.sub.toLowerCase())}`:state.parent==='mods'?`${t('mods')} › ${state.sub==='All'?t('allMods'):t(state.sub.toLowerCase())}`:t('quickFilters')}</summary><div class="category-row">${subs.map(s=>`<button class="chip ${state.sub===s?'selected':''}" data-sub="${esc(s)}">${s==='All'?t('all'):t(s.toLowerCase())}</button>`).join('')}</div>${state.parent==='cas'&&state.sub==='Body'?`<div class="category-row nested-filter">${['Hair','Makeup','Lashes','Eyebrows'].map(s=>`<button class="chip ${state.sub===s?'selected':''}" data-sub="${s}">${t(s.toLowerCase())}</button>`).join('')}</div>`:''}<div class="quick-filters"><label><span>${state.lang==='es'?'Género':'Gender'}</span><select id="gender-filter"><option value="All">${t('all')}</option><option value="Female">${t('female')}</option><option value="Male">${t('male')}</option></select></label><label><span>${state.lang==='es'?'Edad':'Age'}</span><select id="age-filter"><option value="All ages">${t('allages')}</option><option value="Teen">${t('teen')}</option><option value="Young Adult">${t('youngadult')}</option><option value="Kids">${t('kids')}</option><option value="Toddlers">${t('toddlers')}</option></select></label><label><span>${t('style')}</span><select id="style-filter"><option value="All">${t('typeAll')}</option><option>Maxis Match</option><option>Alpha</option></select></label><label><span>${t('source')}</span><select id="source-filter"><option value="All">${t('anysource')}</option>${[...new Set(ITEMS.map(i=>i.source))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label><span>${t('sort')}</span><select id="sort-filter"><option value="curated">${t('curated')}</option><option value="az">${t('az')}</option><option value="updated">${t('updated')}</option><option value="popular">${t('popular')}</option></select></label></div></details><button class="small-chip filter-clear" id="clear-filters">${t('removeFilter')}</button></div><div class="section-toolbar"><h2>${state.parent==='all'?t('all'):t(state.parent)} <span>${items.length} ${t('finds')} · ${t('demo')}</span></h2></div>${items.length?`<div class="masonry">${items.map(itemCard).join('')}</div>`:empty()}`;document.getElementById('gender-filter').value=state.gender;document.getElementById('age-filter').value=state.age;document.getElementById('style-filter').value=state.style;document.getElementById('source-filter').value=state.source;document.getElementById('sort-filter').value=state.sort}
function modScanPanel(){
  const result=modsScanResult,files=result?.files||[],query=modsScanQuery.trim().toLowerCase();
  const matching=query?files.filter(f=>`${f.name} ${f.relativePath}`.toLowerCase().includes(query)):files;
  const pages=Math.max(1,Math.ceil(matching.length/MODS_SCAN_PAGE_SIZE));modsScanPage=Math.min(modsScanPage,pages-1);
  const pageFiles=matching.slice(modsScanPage*MODS_SCAN_PAGE_SIZE,(modsScanPage+1)*MODS_SCAN_PAGE_SIZE);
  const progress=modsScanProgress;
  return `<section class="mods-scan-panel"><div class="scan-panel-head"><div><div class="eyebrow">${t('mycc')}</div><h2>${t('scanTitle')}</h2><p>${t('scanIntro')}</p></div><div class="scan-actions"><button class="primary-btn" id="scan-mods" ${modsScanBusy?'disabled':''}>${modsScanBusy?t('scanWorking'):t('scanReady')}</button>${modsScanBusy?`<button class="secondary-btn" id="cancel-mod-scan">${t('scanCancel')}</button>`:''}</div></div>
  ${modsScanBusy?`<div class="scan-progress"><div class="scan-progress-copy"><span>${t('scanProgress')}: ${Number(progress?.visited||0).toLocaleString(state.lang)} · ${t('scanFound')}: ${Number(progress?.found||0).toLocaleString(state.lang)}</span><span>${t('scanWorking')}</span></div><div class="scan-progress-track"><i></i></div></div>`:''}
  ${modsScanError?`<p class="scan-error">${esc(modsScanError)}</p>`:''}
  ${result?`<div class="scan-summary"><b>${Number(files.length).toLocaleString(state.lang)} ${t('scanFound')}</b><span>${Number(result.visited).toLocaleString(state.lang)} ${t('scanProgress').toLowerCase()}</span>${result.unreadableFolders?`<span class="scan-warning">${Number(result.unreadableFolders).toLocaleString(state.lang)} ${t('scanFoldersSkipped')}</span>`:''}${result.cancelled?`<span>${t('scanCancelled')}</span>`:`<span>${t('scanComplete')}</span>`}</div>${files.length?`<div class="library-search-bar scan-search"><label><span>⌕</span><input id="scan-search" type="search" value="${esc(modsScanQuery)}" placeholder="${t('scanSearch')}"></label></div><div class="scan-file-list">${pageFiles.map(file=>`<div class="scan-file-row"><span class="scan-file-icon">${file.extension==='ts4script'?'⚙':'✧'}</span><span><b>${esc(file.name)}</b><small>${esc(file.relativePath)}</small></span><i>.${esc(file.extension)}</i></div>`).join('')}</div><div class="scan-pagination"><button class="small-chip" data-scan-page="-1" ${modsScanPage===0?'disabled':''}>←</button><span>${t('scanPage')} ${modsScanPage+1} ${t('scanOf')} ${pages} · ${matching.length.toLocaleString(state.lang)}</span><button class="small-chip" data-scan-page="1" ${modsScanPage>=pages-1?'disabled':''}>→</button></div>`:`<p class="scan-empty">${t('scanNoFiles')}</p>`}`:`<p class="scan-empty">${t('scanEmpty')}</p>`}</section>`;
}
function updateModsScanProgress(progress){modsScanProgress=progress;const copy=document.querySelector('.scan-progress-copy');if(copy)copy.innerHTML=`<span>${t('scanProgress')}: ${Number(progress.visited||0).toLocaleString(state.lang)} · ${t('scanFound')}: ${Number(progress.found||0).toLocaleString(state.lang)}</span><span>${t('scanWorking')}</span>`;}
function renderLibrary(){const statuses=['All','Installed','Saved','Needs update'];const q=(state.libraryQuery||state.query).trim().toLowerCase();const all=ITEMS.filter(i=>{const s=installState(i);return(s.installed||isInCollection(i))&&(!q||`${i.name} ${i.es} ${i.creator} ${i.category} ${i.sub}`.toLowerCase().includes(q))});const items=all.filter(i=>{const s=installState(i),saved=isInCollection(i);if(state.libraryState==='Installed'&&!s.installed)return false;if(state.libraryState==='Saved'&&(!saved||s.installed))return false;if(state.libraryState==='Needs update'&&!s.needsUpdate)return false;return true});const groupLabel=i=>state.groupMode==='creator'?i.creator:(state.lang==='es'?categoryLabel(i.category):i.category);const grouped=state.groupMode==='creator'?CREATORS.map(c=>[c.name,items.filter(i=>i.creator===c.name)]).filter(x=>x[1].length):[...new Set(items.map(groupLabel))].sort().map(k=>[k,items.filter(i=>groupLabel(i)===k)]);content.innerHTML=`${heading(t('mycc').toUpperCase(),t('libraryTitle'),t('libraryText'))}${typeof folderRoutePanel==='function'?folderRoutePanel():''}${modScanPanel()}<div class="library-search-bar"><label><span>⌕</span><input id="library-search" type="search" value="${esc(state.libraryQuery)}" placeholder="${t('librarySearch')}"></label><small>${t('librarySearchHint')}</small></div><div class="subtabs">${statuses.map(s=>`<button class="small-chip ${state.libraryState===s?'active':''}" data-library-state="${s}">${t(s==='All'?'all':s==='Installed'?'installed':s==='Saved'?'saved':'needsUpdate')}</button>`).join('')}</div><div class="library-toolbar"><div class="section-toolbar"><h2>${t(state.libraryState==='All'?'allCC':state.libraryState==='Installed'?'installed':state.libraryState==='Saved'?'saved':'needsUpdate')} <span>${items.length} ${t('demo')}</span></h2><label>${t('groupBy')} <select id="group-mode"><option value="category">${t('category')}</option><option value="creator">${t('creator')}</option></select></label></div></div>${items.length?grouped.map(([name,group])=>`<section class="library-group"><div class="section-toolbar"><h2>${esc(name)} <span>${group.length}</span></h2></div><div class="masonry">${group.map(itemCard).join('')}</div></section>`).join(''):empty(t('libraryEmpty'))}`;document.getElementById('group-mode').value=state.groupMode}
function recentBoards(){return getBoards().sort((a,b)=>(b.used||0)-(a.used||0)).slice(0,6)}
function recommendedItems(){const saved=ITEMS.filter(i=>state.favorites.includes(i.id)||state.collections.some(c=>c.items.includes(i.id)));const want=saved.length?saved[0].type:null;return ITEMS.filter(i=>!state.favorites.includes(i.id)).sort((a,b)=>(want&&b.type===want?1:0)-(want&&a.type===want?1:0)).slice(0,3)}
function boardPreview(b,index){const refs=b.refs.map(id=>REFERENCES.find(r=>r.id===id)).filter(Boolean).slice(0,3),defaults=[['🛋️','💐','🪞'],['🏡','🌿','🕯️'],['👗','👜','🌷'],['💄','🪻','✧'],['🪑','🪴','🧸'],['🎨','🌼','☼']][index%6];return `<div class="board-collage">${[0,1,2].map(slot=>{const ref=refs[slot];return `<div class="collage-tile" ${ref?`style="--tile-bg:${esc(ref.bg)}"`:''}>${ref?.emoji||defaults[slot]}</div>`}).join('')}</div>`}
function renderInspiration(){const boards=recentBoards(),recommendations=recommendedItems();content.innerHTML=`${heading(t('inspiration').toUpperCase(),t('inspiration'),state.lang==='es'?'Referencias visuales de Pinterest con CC relacionado para llevar la idea al juego.':'Pinterest visual references with related CC to bring each idea into your game.')}<div class="inspo-columns"><section><div class="section-toolbar"><h2>${t('recentBoards')} <span>6</span></h2><button class="small-chip" id="new-board">＋ ${t('newBoard')}</button></div><div class="board-grid">${boards.map((b,i)=>`<article class="board-card" data-board="${esc(b.id)}">${boardPreview(b,i)}<div class="board-label"><strong>${esc(boardLabel(b))}</strong><span>${b.refs.length} ${t('pins')}</span></div></article>`).join('')}</div><div class="section-toolbar" style="margin-top:27px"><h2>${t('pinterest')} <span>${t('demo')}</span></h2><button class="small-chip" id="upload-reference">＋ ${state.lang==='es'?'Subir imagen':'Upload image'}</button></div><div class="masonry">${REFERENCES.map(refCard).join('')}</div></section><aside class="recommend-panel"><div class="eyebrow">✦ ${t('recommendations')}</div><p>${t('noRecommendations')}</p><div class="recommend-list">${recommendations.map(i=>`<div class="recommend-item">${art(i,'recommend-art')}<div><strong>${esc(labelItem(i))}</strong><small>${esc(i.creator)} · ${esc(i.type)}</small><button class="text-link" data-detail="${i.id}">${t('openDetails')} →</button></div></div>`).join('')}</div></aside></div>`}
function creatorCard(c){const following=state.followingCreators.includes(c.id),platformControl=c.platforms.length>1?`<label class="creator-platform-picker"><span>${t('choosePlatform')}</span><select data-creator-link="${esc(c.id)}"><option value="">${t('visit')}…</option>${c.platforms.map((p,i)=>`<option value="${i}">${esc(p[0])}</option>`).join('')}</select></label>`:`<a class="creator-visit" href="${esc(c.platforms[0][1])}" target="_blank" rel="noopener noreferrer">${t('visit')} ${esc(c.platforms[0][0])} ↗</a>`;return `<article class="creator-card creator-card-soft"><header class="creator-soft-head"><div class="creator-avatar">${esc(c.icon)}</div><div class="creator-identity"><h3>${esc(c.name)}</h3><div class="platform">${c.platforms.map(p=>esc(p[0])).join(' · ')}</div></div><span class="creator-style-pill">${c.manualPatreon?t('creatorAddedByYou'):esc(c.type==='Both'?t('both'):styleLabel(c.type))}</span></header><div class="creator-soft-tags">${c.tags.slice(0,3).map(tag=>`<span>${esc(tagLabel(tag))}</span>`).join('')}</div><div class="creator-soft-footer">${platformControl}<button class="small-chip creator-follow ${following?'active':''}" data-follow-creator="${esc(c.id)}" aria-pressed="${following}">${following?'♥ ':''}${following?t('followingCreator'):t('followCreator')}</button>${c.manualPatreon?`<button class="small-chip creator-remove" data-remove-patreon-creator="${esc(c.id)}">${t('removePatreonCreator')}</button>`:`<span class="creator-kinds">${esc(state.lang==='es'?c.esStyle:c.style)}</span>`}</div>${c.manualPatreon?`<p class="creator-local-note">${t('patreonProfileLink')}</p>`:''}</article>`}
function renderCreators(){const creators=creatorCatalog(),query=state.query.toLowerCase(),filtered=creators.filter(c=>(state.creatorPlatform==='All'||c.platforms.some(p=>p[0]===state.creatorPlatform))&&(!state.creatorFollowingOnly||state.followingCreators.includes(c.id))&&(!state.query||`${c.name} ${c.tags.join(' ')} ${c.style}`.toLowerCase().includes(query)));const platforms=['All',...new Set(creators.flatMap(c=>c.platforms.map(p=>p[0])))];content.innerHTML=`${heading(t('creators').toUpperCase(),t('creators'),state.lang==='es'?'Perfiles de creadores agrupados para que encuentres su contenido y plataformas.':'Creator profiles grouped so you can find their content and platforms.')}<section class="patreon-status"><div class="patreon-status-mark">P</div><div><strong>${t('patreonPostsTitle')}</strong><p>${t('patreonPostsNote')}</p></div></section><div class="creator-toolbar"><label>${t('creatorFilter')}<select id="creator-platform"><option value="All">${t('allPlatforms')}</option>${platforms.slice(1).map(p=>`<option>${esc(p)}</option>`).join('')}</select></label><div class="creator-toolbar-actions"><button class="small-chip ${state.creatorFollowingOnly?'active':''}" id="creator-following-filter" aria-pressed="${state.creatorFollowingOnly}">${state.creatorFollowingOnly?'♥ ':''}${state.creatorFollowingOnly?t('followingOnly'):t('allCreators')} · ${state.followingCreators.length}</button><button class="primary-btn" id="add-patreon-creator">＋ ${t('addPatreonCreator')}</button><span>${t('demo')} · ${t('sourceDemo')}</span></div></div><div class="creator-grid">${filtered.map(creatorCard).join('')}</div>${filtered.length?'':empty(t('noResult'))}`;document.getElementById('creator-platform').value=state.creatorPlatform}
function addPatreonCreatorDialog(){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">Patreon · ${t('creatorAddedByYou')}</div><h2 id="dialog-title">${t('addPatreonCreator')}</h2><p>${t('patreonManualNote')}</p><label>${t('creatorName')}<input id="patreon-creator-name" type="text" maxlength="70" autocomplete="off" placeholder="${t('creatorName')}"></label><label>${t('patreonProfileUrl')}<input id="patreon-profile-url" type="url" inputmode="url" autocomplete="url" placeholder="${t('patreonProfilePlaceholder')}"></label><div class="detail-actions"><button class="primary-btn" id="save-patreon-creator">${t('addPatreonCreator')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function savePatreonCreator(){const name=document.getElementById('patreon-creator-name')?.value.trim(),input=document.getElementById('patreon-profile-url')?.value.trim(),profileUrl=normalizePatreonProfile(input);if(!name||!input){toast(t('patreonNameRequired'));return}if(!profileUrl){toast(t('patreonUrlInvalid'));return}const saved=localPatreonCreators();if(saved.some(c=>c.profileUrl===profileUrl)){toast(t('patreonDuplicate'));return}const id=`patreon-custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;saved.push({id,name,profileUrl,icon:'P',platforms:[['Patreon',profileUrl]],tags:[],type:'Unknown',style:'Patreon profile',esStyle:'Perfil de Patreon',manualPatreon:true});if(!safeWrite('patreon-creators',saved)){toast(t('patreonSaveFailed'));return}closeDialog();state.creatorPlatform='All';state.creatorFollowingOnly=false;state.query='';search.value='';renderCreators();toast(t('patreonCreatorAdded'))}
function renderCollection(){const c=state.collections.find(x=>x.id===state.activeCollection);if(!c){state.page='discover';return render()}const items=ITEMS.filter(i=>i.isCC!==false&&c.items.includes(i.id));content.innerHTML=`${heading(t('collectionsTitle').toUpperCase(),esc(collectionLabel(c)),t('collectionsText'))}<div class="collection-actions"><button class="primary-btn" data-export="${c.id}">${t('share')}</button><button class="secondary-btn" id="import-collection-button">${t('importCollection')}</button><button class="small-chip" id="rename-collection">${t('rename')}</button><button class="small-chip cover-image-button" disabled title="${t('coverSoon')}">▧ ${t('coverImage')}</button></div><p class="muted-note">${t('onlyLinks')}</p><div class="section-toolbar"><h2>${t('downloadable')} <span>${items.length} ${t('demo')}</span></h2></div>${items.length?`<div class="masonry">${items.map(itemCard).join('')}</div>`:empty(t('noCC'),t('onlyLinks'))}`}
function collectionPreview(c){const items=ITEMS.filter(i=>c.items.includes(i.id)).slice(0,3),defaults=['✧','✿','☼'];return `<div class="collection-cover-collage">${[0,1,2].map(slot=>{const item=items[slot];return `<div class="collection-cover-tile ${item?'has-art':''}" ${item?`style="--cover-art:${esc(item.bg)}"`:''}>${item?.emoji||defaults[slot]}</div>`}).join('')}</div>`}
function renderCollections(){const downloadable=new Set(ITEMS.filter(i=>i.isCC!==false).map(i=>i.id));state.collections.forEach(c=>c.items=c.items.filter(id=>downloadable.has(id)));content.innerHTML=`${heading(t('collectionsTitle').toUpperCase(),t('collectionsTitle'),t('collectionsText'))}<div class="collection-actions"><button class="primary-btn" id="new-collection-page">＋ ${t('newCollection')}</button><button class="secondary-btn" id="import-collection-button">${t('importCollection')}</button></div><div class="collection-grid">${state.collections.map(c=>`<article class="collection-tile" data-collection="${c.id}">${collectionPreview(c)}<div class="collection-tile-info"><strong>${esc(collectionLabel(c))}</strong><span>${esc(c.items.length)} · →</span></div></article>`).join('')}</div>`}
function themeOption(mode,title,key){const active=state.theme===mode?'active':'';return `<button class="theme-option theme-swatch ${active}" data-theme="${mode}"><i class="swatch-dot"></i><span>${title}</span><small>${t(key)}</small></button>`}
function renderSettings(){content.innerHTML=`${heading(t('settingsTitle').toUpperCase(),t('settingsTitle'),t('settingsText'))}<div class="settings-grid"><details class="setting-card theme-card theme-disclosure" ${state.theme.startsWith('soft')?'open':''}><summary><span><b>${t('softLight')}</b><small>${state.lang==='es'?'Tres acentos pastel':'Three pastel accents'}</small></span><i>⌄</i></summary><div class="theme-options">${themeOption('soft-rose',t('rose'),'softLight')}${themeOption('soft-lavender',t('lavender'),'softLight')}${themeOption('soft-sage',t('sage'),'softLight')}</div></details><details class="setting-card theme-card theme-disclosure" ${state.theme.startsWith('dark')?'open':''}><summary><span><b>${t('afterHours')}</b><small>${state.lang==='es'?'Tres acentos oscuros':'Three dark accents'}</small></span><i>⌄</i></summary><div class="theme-options">${themeOption('dark-rose',t('rose'),'afterHours')}${themeOption('dark-lavender',t('lavender'),'afterHours')}${themeOption('dark-sage',t('sage'),'afterHours')}</div></details><section class="setting-card"><h3>${t('organization')}</h3><p>${state.lang==='es'?'Elige cómo agrupar los elementos de Mi CC.':'Choose how items are grouped in My CC.'}</p><label>${t('groupBy')} <select id="group-mode-settings"><option value="category">${t('category')}</option><option value="creator">${t('creator')}</option></select></label></section><section class="setting-card"><h3>${t('language')}</h3><p>${state.lang==='es'?'El idioma se aplica a toda la interfaz.':'Language applies across the whole interface.'}</p><div class="theme-options"><button class="theme-option ${state.lang==='es'?'active':''}" data-language="es">Español</button><button class="theme-option ${state.lang==='en'?'active':''}" data-language="en">English</button></div></section><section class="setting-card"><h3>${t('about')}</h3><p>${t('version')}: <b>${APP_VERSION} ${state.lang==='es'?'prototipo visual':'visual prototype'}</b><br>${t('compatibility')}: <b>${t('local')} · ${t('windows')}</b><br>${t('sourceDemo')}</p></section><section class="setting-card"><h3>${t('signIn')}</h3><p>${t('accountText')}</p><button class="secondary-btn" disabled>${t('signIn')} · ${t('comingSoon')}</button></section><section class="setting-card"><h3>${t('feedback')} / ${t('donate')}</h3><p>${state.lang==='es'?'Comparte ideas para mejorar SimmerSpace. Las donaciones estarán disponibles cuando exista un sitio oficial.':'Share ideas to improve SimmerSpace. Donations will be available when the project has an official home.'}</p><button class="secondary-btn" id="send-feedback">${t('feedback')}</button><button class="small-chip" id="donate-button">${t('donate')} · ${t('comingSoon')}</button></section></div>${typeof folderSettingsSection==='function'?folderSettingsSection():''}`;document.getElementById('group-mode-settings').value=state.groupMode}
function renderFavorites(){const items=ITEMS.filter(i=>state.favorites.includes(i.id));content.innerHTML=`${heading(t('favorite').toUpperCase(),t('favorite'),state.lang==='es'?'Tus CC favoritos.':'Your favorite CC finds.')}${items.length?`<div class="masonry">${items.map(itemCard).join('')}</div>`:empty()}`}
function render(){setShell();const pages={discover:renderDiscover,mycc:renderLibrary,inspiration:renderInspiration,creators:renderCreators,settings:renderSettings,collection:renderCollection,collections:renderCollections,favorites:renderFavorites};(pages[state.page]||renderDiscover)()}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function openDialog(html){dialog.innerHTML=html;overlay.hidden=false;dialog.querySelector('input,textarea,select')?.focus()}
function closeDialog(){overlay.hidden=true;dialog.innerHTML=''}
function newCollectionDialog(){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('collectionsTitle')}</div><h2 id="dialog-title">${t('newCollection')}</h2><p>${t('downloadable')} · ${t('demo')}</p><input id="collection-name" maxlength="40" placeholder="${state.lang==='es'?'Nombre de la colección':'Collection name'}"><div class="detail-actions"><button class="primary-btn" id="create-collection">${t('create')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function saveDialog(id){const item=ITEMS.find(i=>i.id===id);if(!item)return;if(item.isCC===false){toast(t('noCC'));return}openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('downloadable')}</div><h2 id="dialog-title">${t('save')}</h2><p>${esc(labelItem(item))} · ${t('demo')}</p>${state.collections.map(c=>`<label class="check-collection"><input type="checkbox" value="${c.id}" ${c.items.includes(id)?'checked':''}> ${esc(collectionLabel(c))}</label>`).join('')}<button class="small-chip" id="new-collection-from-save">＋ ${t('newCollection')}</button><div class="detail-actions"><button class="primary-btn" id="confirm-save" data-item="${id}">${t('save')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function detailDialog(item){const installed=installState(item).installed;openDialog(`<button class="dialog-close" data-close>×</button>${art(item,'detail-art')}<div class="detail-body"><div class="eyebrow">${esc(categoryLabel(item.category))} · ${esc(item.source)} · ${t('demo')}</div><h2 id="dialog-title">${esc(labelItem(item))}</h2><div class="card-creator">${esc(item.creator)} · ${esc(styleLabel(item.type))}</div><p>${esc(labelItem(item,'note'))}</p><div class="tag-row"><span class="meta-pill">${esc(audienceLabel(item.gender))}</span><span class="meta-pill">${esc(audienceLabel(item.age))}</span><span class="meta-pill">${esc(item.source)}</span></div><div class="detail-actions"><button class="primary-btn" data-toggle-install="${item.id}">${installed?t('uninstall'):t('install')}</button><button class="secondary-btn" data-save="${item.id}">${t('save')}</button><button class="secondary-btn download-demo" disabled title="${t('downloadLinks')}">↓ ${t('downloadItem')}</button><button class="secondary-btn" data-favorite="${item.id}">${state.favorites.includes(item.id)?'♥':'♡'} ${t('favorite')}</button></div><p class="demo-disclaimer">${t('downloadLinks')}</p></div>`)}
function toggleFavorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render();toast(state.favorites.includes(id)?t('favoriteAdded'):t('favoriteRemoved'))}
function saveSelection(id){const selected=[...dialog.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value);state.collections.forEach(c=>{c.items=c.items.filter(i=>i!==id);if(selected.includes(c.id))c.items.push(id)});persist();closeDialog();render();toast(t('collectionSaved'))}
function createCollection(){const input=document.getElementById('collection-name'),name=input?.value.trim();if(!name){input?.focus();return}const id='collection-'+Date.now().toString(36);state.collections.push({id,name,items:[]});persist();closeDialog();render();toast(t('collectionSaved'))}
function collectionLink(c){const payload={format:'simmerspace-collection-link-v1',name:c.name,items:c.items.filter(id=>ITEMS.some(i=>i.id===id))};const url=new URL(window.location.href);url.hash=`collection=${encodeURIComponent(JSON.stringify(payload))}`;return url.href}
function readCollectionLink(value){try{const url=new URL(value.trim(),window.location.href);const raw=new URLSearchParams(url.hash.replace(/^#/,'' )).get('collection');if(!raw)return null;const data=JSON.parse(raw);if(data.format!=='simmerspace-collection-link-v1'||!Array.isArray(data.items))return null;return{name:String(data.name||'Imported collection').slice(0,40),items:data.items.filter(id=>typeof id==='string'&&ITEMS.some(i=>i.id===id))}}catch{return null}}
async function shareCollection(id){const c=state.collections.find(x=>x.id===id);if(!c)return;const link=collectionLink(c);openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('collectionsTitle')}</div><h2 id="dialog-title">${t('share')}</h2><p>${t('linkShareHint')}</p><input id="collection-share-link" readonly value="${esc(link)}"><div class="detail-actions"><button class="primary-btn" id="copy-collection-link">${t('copyLink')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function importCollectionFromLink(value){const data=readCollectionLink(value);if(!data){toast(t('invalidCollectionLink'));return false}const id='import-'+Date.now().toString(36);state.collections.push({id,name:data.name,items:data.items});persist();closeDialog();render();toast(t('imported'));return true}
function importCollectionDialog(value=''){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('collectionsTitle')}</div><h2 id="dialog-title">${t('importCollection')}</h2><p>${t('pasteCollectionLink')}</p><input id="collection-link-input" type="url" placeholder="https://…" value="${esc(value)}"><div class="detail-actions"><button class="primary-btn" id="import-collection-link">${t('importLink')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function offerSharedCollection(){const raw=location.hash.startsWith('#collection=')?location.href:'';if(raw){const data=readCollectionLink(raw);history.replaceState(null,'',location.pathname+location.search);if(data)importCollectionDialog(raw)}}
function newBoardDialog(){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('inspiration')}</div><h2 id="dialog-title">${t('newBoard')}</h2><input id="board-name" maxlength="42" placeholder="${state.lang==='es'?'Nombre del tablero':'Board name'}"><textarea id="board-note" placeholder="${t('boardNote')}"></textarea><div class="detail-actions"><button class="primary-btn" id="create-board">${t('create')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function openBoard(id){const boards=getBoards(),board=boards.find(b=>b.id===id);if(!board)return;board.used=Date.now();safeWrite('boards',boards);state.activeBoard=id;const rec=ITEMS.filter(i=>i.category==='Furniture'||i.department==='buildbuy').slice(0,2);openDialog(`<button class="dialog-close" data-close>×</button><div class="board-detail-layout"><div class="form-dialog"><div class="eyebrow">${t('pinterest')} · ${t('demo')}</div><h2 id="dialog-title">${esc(boardLabel(board))}</h2><p>${t('boardNote')}</p><textarea id="board-note-edit">${esc(boardDescription(board))}</textarea><div class="board-reference-list">${REFERENCES.filter(r=>board.refs.includes(r.id)).map(r=>refCard(r)).join('')||`<p class="muted-note">${t('pinterest')} · ${t('demo')}</p>`}</div><div class="detail-actions"><button class="primary-btn" id="save-board-note" data-save-board-note="${id}">${t('saveNote')}</button><button class="secondary-btn" id="add-reference">＋ ${t('addReference')}</button><button class="secondary-btn danger-quiet" data-delete-board="${id}">${t('deleteBoard')}</button></div></div><aside class="related-panel"><div class="eyebrow">✦ ${t('relatedCC')}</div>${rec.map(i=>`<div class="recommend-item">${art(i,'recommend-art')}<div><strong>${esc(labelItem(i))}</strong><small>${esc(i.creator)} · ${esc(i.type)}</small><button class="text-link" data-save="${i.id}">${t('save')}</button></div></div>`).join('')}</aside></div>`)}
function pinReference(id){const boards=getBoards();openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('pinterest')}</div><h2 id="dialog-title">${t('addReference')}</h2>${boards.map(b=>`<label class="check-collection"><input type="radio" name="pin-board" value="${b.id}"> ${esc(boardLabel(b))}</label>`).join('')}<div class="detail-actions"><button class="primary-btn" id="confirm-pin" data-ref="${id}">${t('save')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
function createBoard(){const name=document.getElementById('board-name').value.trim();if(!name){document.getElementById('board-name').focus();return}const boards=getBoards();boards.unshift({id:'board-'+Date.now().toString(36),name,emoji:'✧',refs:[],note:document.getElementById('board-note').value.trim(),used:Date.now()});safeWrite('boards',boards);closeDialog();render();toast(t('collectionSaved'))}
function openFeedback(){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><div class="eyebrow">${t('feedback')}</div><h2 id="dialog-title">${t('feedback')}</h2><p>${t('suggestionSaved')}</p><textarea id="feedback-note" placeholder="${t('boardNote')}"></textarea><div class="detail-actions"><button class="primary-btn" id="save-feedback">${t('send')}</button><button class="secondary-btn" data-close>${t('cancel')}</button></div></div>`)}
document.addEventListener('click',async e=>{
  if(e.target.closest('#scan-mods')){if(!window.simmerSpace?.scanMods){modsScanError=t('scanError');renderLibrary();return}modsScanBusy=true;modsScanError='';modsScanProgress={visited:0,found:0};renderLibrary();try{modsScanResult=await window.simmerSpace.scanMods();modsScanPage=0;modsScanQuery=''}catch(error){modsScanError=error?.message?.includes('Choose your Mods folder')?t('scanRequired'):(error?.message||t('scanError'))}finally{modsScanBusy=false;if(state.page==='mycc')renderLibrary()}return}
  if(e.target.closest('#cancel-mod-scan')){window.simmerSpace?.cancelModsScan();return}
  const scanPage=e.target.closest('[data-scan-page]');if(scanPage){modsScanPage=Math.max(0,modsScanPage+Number(scanPage.dataset.scanPage));renderLibrary();return}
  const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;state.query='';search.value='';render();return}
  const collection=e.target.closest('[data-collection]');if(collection){state.page='collection';state.activeCollection=collection.dataset.collection;render();return}
  const parent=e.target.closest('[data-parent]');if(parent){state.parent=parent.dataset.parent;state.sub='All';render();return}
  const sub=e.target.closest('[data-sub]');if(sub){state.sub=sub.dataset.sub;render();return}
   const library=e.target.closest('[data-library-state]');if(library){state.libraryState=library.dataset.libraryState;render();return}
   const install=e.target.closest('[data-toggle-install]');if(install){const id=install.dataset.toggleInstall,old=state.statuses[id],currently=installState(ITEMS.find(i=>i.id===id)).installed;state.statuses[id]={installed:!currently,needsUpdate:false};persist();closeDialog();render();toast(t(!currently?'install':'uninstall'));return}
  const theme=e.target.closest('[data-theme]');if(theme){state.theme=theme.dataset.theme;safeSet('simmerspace-theme',state.theme);render();return}
  const lang=e.target.closest('[data-language]');if(lang){state.lang=lang.dataset.language;safeSet('simmerspace-language',state.lang);render();return}
  const favorite=e.target.closest('[data-favorite]');if(favorite){e.stopPropagation();toggleFavorite(favorite.dataset.favorite);return}
  const followCreator=e.target.closest('[data-follow-creator]');if(followCreator){const id=followCreator.dataset.followCreator;state.followingCreators=state.followingCreators.includes(id)?state.followingCreators.filter(value=>value!==id):[...state.followingCreators,id];safeWrite('following-creators',state.followingCreators);renderCreators();toast(state.followingCreators.includes(id)?t('creatorFollowSaved'):t('creatorFollowRemoved'));return}
  if(e.target.closest('#creator-following-filter')){state.creatorFollowingOnly=!state.creatorFollowingOnly;renderCreators();return}
   const removePatreon=e.target.closest('[data-remove-patreon-creator]');if(removePatreon){if(confirm(t('confirmRemovePatreon'))){const id=removePatreon.dataset.removePatreonCreator;safeWrite('patreon-creators',localPatreonCreators().filter(c=>c.id!==id));state.followingCreators=state.followingCreators.filter(value=>value!==id);safeWrite('following-creators',state.followingCreators);renderCreators();toast(t('patreonCreatorRemoved'))}return}
  const save=e.target.closest('[data-save]');if(save){e.stopPropagation();saveDialog(save.dataset.save);return}
  const pin=e.target.closest('[data-pin-ref]');if(pin){e.stopPropagation();pinReference(pin.dataset.pinRef);return}
  const detail=e.target.closest('[data-detail]');if(detail){const item=ITEMS.find(i=>i.id===detail.dataset.detail);if(item)detailDialog(item);return}
  const board=e.target.closest('[data-board]');if(board){openBoard(board.dataset.board);return}
  const deleteBoard=e.target.closest('[data-delete-board]');if(deleteBoard){if(confirm(t('confirmDeleteBoard'))){const boards=getBoards().filter(b=>b.id!==deleteBoard.dataset.deleteBoard);safeWrite('boards',boards);closeDialog();render();toast(t('deleteBoard'))}return}
  if(e.target.closest('[data-close]')){closeDialog();return}
  if(e.target.id==='new-collection'||e.target.id==='new-collection-page'||e.target.id==='new-collection-from-save'){newCollectionDialog();return}
  if(e.target.id==='create-collection'){createCollection();return}
  if(e.target.id==='confirm-save'){saveSelection(e.target.dataset.item);return}
  if(e.target.id==='theme-toggle'){const hue=state.theme.split('-')[1]||'lavender';state.theme=state.theme.startsWith('dark')?`soft-${hue}`:`dark-${hue}`;safeSet('simmerspace-theme',state.theme);render();return}
  if(e.target.id==='new-board'){newBoardDialog();return}
   if(e.target.id==='add-patreon-creator'){addPatreonCreatorDialog();return}
   if(e.target.id==='save-patreon-creator'){savePatreonCreator();return}
  if(e.target.id==='create-board'){createBoard();return}
  if(e.target.id==='save-board-note'){const boards=getBoards(),b=boards.find(x=>x.id===e.target.dataset.saveBoardNote);if(b){b.note=document.getElementById('board-note-edit').value.trim();b.used=Date.now();safeWrite('boards',boards);closeDialog();render();toast(t('noteSaved'))}return}
  if(e.target.id==='add-reference'){pinReference('ref-sunroom');return}
  if(e.target.id==='confirm-pin'){const selected=dialog.querySelector('input[name="pin-board"]:checked');if(!selected){toast(t('noResult'));return}const boards=getBoards(),b=boards.find(x=>x.id===selected.value);if(b&&!b.refs.includes(e.target.dataset.ref)){b.refs.push(e.target.dataset.ref);b.used=Date.now();safeWrite('boards',boards)}closeDialog();render();toast(t('pinAdded'));return}
  if(e.target.id==='import-collection-button'){importCollectionDialog();return}
  if(e.target.id==='import-collection-link'){importCollectionFromLink(document.getElementById('collection-link-input')?.value||'');return}
  if(e.target.id==='copy-collection-link'){const field=document.getElementById('collection-share-link');field?.select();try{await navigator.clipboard.writeText(field.value)}catch{document.execCommand('copy')}toast(t('shareFile'));return}
  if(e.target.id==='rename-collection'){const c=state.collections.find(x=>x.id===state.activeCollection);if(c){openDialog(`<button class="dialog-close" data-close>×</button><div class="form-dialog"><h2 id="dialog-title">${t('rename')}</h2><input id="collection-name" value="${esc(collectionLabel(c))}"><button class="primary-btn" id="save-rename">${t('save')}</button></div>`)}return}
  if(e.target.id==='save-rename'){const c=state.collections.find(x=>x.id===state.activeCollection),name=document.getElementById('collection-name').value.trim();if(c&&name){c.name=name;persist();closeDialog();render()}return}
  if(e.target.id==='send-feedback'){openFeedback();return}
  if(e.target.id==='save-feedback'){const notes=safeRead('suggestions',[]);notes.push({text:document.getElementById('feedback-note').value.trim(),date:new Date().toISOString()});safeWrite('suggestions',notes);closeDialog();toast(t('suggestionSaved'));return}
  if(e.target.id==='donate-button'){toast(t('donationDemo'));return}
  if(e.target.id==='profile-button'){toast(t('loginDemo'));return}
  if(e.target.id==='upload-reference'){toast(t('planned'));return}
  if(e.target.id==='clear-filters'){state.parent='all';state.sub='All';state.gender='All';state.age='All ages';state.style='All';state.source='All';state.sort='curated';state.query='';search.value='';render();return}
  const exp=e.target.closest('[data-export]');if(exp){shareCollection(exp.dataset.export);return}
  if(e.target.id==='show-all-collections'){state.page='collections';render();return}
});
document.addEventListener('change',e=>{if(e.target.id==='group-mode'||e.target.id==='group-mode-settings'){state.groupMode=e.target.value;safeSet('simmerspace-group-mode',state.groupMode);if(state.page==='settings')renderSettings();else renderLibrary()}if(e.target.id==='gender-filter'){state.gender=e.target.value;render()}if(e.target.id==='age-filter'){state.age=e.target.value;render()}if(e.target.id==='style-filter'){state.style=e.target.value;render()}if(e.target.id==='source-filter'){state.source=e.target.value;render()}if(e.target.id==='sort-filter'){state.sort=e.target.value;render()}if(e.target.id==='creator-platform'){state.creatorPlatform=e.target.value;render()}const link=e.target.closest('[data-creator-link]');if(link&&link.value!==''){const creator=creatorCatalog().find(c=>c.id===link.dataset.creatorLink),platform=creator?.platforms[Number(link.value)];if(platform){try{const target=new URL(platform[1]);if(target.protocol==='https:')window.open(target.href,'_blank','noopener,noreferrer')}catch{}}link.value=''}});
document.addEventListener('input',e=>{if(e.target.id==='scan-search'){const cursor=e.target.selectionStart;modsScanQuery=e.target.value;modsScanPage=0;renderLibrary();const field=document.getElementById('scan-search');field.focus();field.setSelectionRange(cursor,cursor)}if(e.target.id==='library-search'){const cursor=e.target.selectionStart;state.libraryQuery=e.target.value;renderLibrary();const field=document.getElementById('library-search');field.focus();field.setSelectionRange(cursor,cursor)}});
search.addEventListener('input',()=>{state.query=search.value;if(state.page==='mycc')state.libraryQuery='';if(!['discover','mycc','creators'].includes(state.page))state.page='discover';render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search.focus()}});
overlay.addEventListener('click',e=>{if(e.target===overlay)closeDialog()});
if(window.simmerSpace?.onScanProgress)window.simmerSpace.onScanProgress(updateModsScanProgress);
render();
offerSharedCollection();
